{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "MTX-241F, a structurally related aminopyrimidine-containing inhibitor, achieved micromolar brain tissue levels in mice and was characterized as brain-penetrant, supporting CNS access for the query's aminopyrimidine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Lorlatinib showed CSF-to-free plasma ratios of 0.61–0.96 in a phase 1/2 study, directly demonstrating efficient BBB penetration; its high transferability supports the query's likely CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "PRE-084, a morpholine-containing compound, reached 773.6 ng/g brain at Tmax in mice with rapid CNS distribution, supporting the query's morpholine-containing scaffold as CNS-permeable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "MW150 had a rat brain/plasma ratio >0.9 at 3 h, demonstrating distribution across the BBB and supporting the query's heteroaromatic CNS-penetrant phenotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "SHP099 showed brain-plasma ratio >1 from 1 to 24 h in mice, providing direct evidence that this class of aminopyridine/aminopyrimidine kinase inhibitor achieves efficacious brain concentrations.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple highly transferable analogues with direct brain, CSF, or brain/plasma measurements demonstrate meaningful CNS access, and no contradictory evidence was retrieved; the query is predicted to have adequate BBB/CNS penetration.",
  "evidence_gaps": [
    "No direct experimental PK or brain concentration data for the query molecule itself.",
    "Exact P-glycoprotein/BCRP efflux liability of the query is not directly measured, though several supportive analogues are known to overcome or avoid efflux."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

